195	    /**
196	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
197	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
198	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
199	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
200	     * postcode nor the city identifies a region.
201	     *
202	     * @param owner the owner being created
203	     * @return the derived region code, never {@code null}
204	     */
205	    private String regionCode(Owner owner) {
206	        String fromPostcode = regionFromPostcode(owner.getPostcode());
207	        if (fromPostcode != null) {
208	            return fromPostcode;
209	        }
210	        String fromCity = region(owner.getCity());
211	        return fromCity == null ? "UNKNOWN" : fromCity;
212	    }
