214	    /**
215	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
216	     * postcode is absent, not 4 digits, or in no known range.
217	     *
218	     * @param postcode the owner's postcode, may be {@code null}
219	     * @return the region code, or {@code null} when no known range contains the postcode
220	     */
221	    private String regionFromPostcode(String postcode) {
222	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
223	            return null;
224	        }
225	        int value = Integer.parseInt(postcode);
226	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
227	            int[] range = entry.getValue();
228	            if (value >= range[0] && value <= range[1]) {
229	                return entry.getKey();
230	            }
231	        }
232	        return null;
233	    }
