393	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
394	     */
395	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
396	        "NSW", new int[] {2000, 2099},
397	        "VIC", new int[] {3000, 3099},
398	        "QLD", new int[] {4000, 4099});
