400	    /**
401	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
402	     * is optional and accepted, keeping the create contract backward-compatible. When present the
403	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
404	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
405	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
406	     *
407	     * @param postcode the raw postcode value as submitted, may be {@code null}
408	     * @param city     the owner's city, used to resolve the region whose range applies
409	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
410	     *                                  the city's region
411	     */
412	    private void validatePostcode(String postcode, String city) {
413	        if (isBlank(postcode)) {
414	            return;
415	        }
416	        if (!postcode.matches("[0-9]{4}")) {
417	            throw new InvalidPostcodeException(postcode, city);
418	        }
419	        String region = region(city);
420	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
421	        if (range != null) {
422	            int value = Integer.parseInt(postcode);
423	            if (value < range[0] || value > range[1]) {
424	                throw new InvalidPostcodeException(postcode, city);
425	            }
426	        }
427	    }
