429	    /**
430	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
431	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
432	     *
433	     * @param city the owner's city
434	     * @return the region code, or {@code null} when the city has no known region
435	     */
436	    private String region(String city) {
437	        if (city == null) {
438	            return null;
439	        }
440	        return switch (city) {
441	            case "Sydney" -> "NSW";
442	            case "Melbourne" -> "VIC";
443	            case "Brisbane" -> "QLD";
444	            default -> null;
445	        };
446	    }
