456	    /**
457	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
458	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
459	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
460	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
461	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
462	     *
463	     * @param telephone the raw telephone value as submitted
464	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
465	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
466	     *                                   national-number length is wrong for its country code
467	     */
468	    private String normalizeTelephone(String telephone) {
469	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
470	        String nationalSignificantNumber;
471	        if (cleaned.startsWith("+")) {
472	            nationalSignificantNumber = cleaned.substring(1);
473	        } else {
474	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
475	            nationalSignificantNumber = "61" + national;
476	        }
477	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
478	            throw new InvalidTelephoneException(telephone);
479	        }
480	        validateNationalNumberLength(nationalSignificantNumber, telephone);
481	        return "+" + nationalSignificantNumber;
482	    }
483	
484	    /**
485	     * Validates the national-number length of an E.164 number against its country calling code. The
486	     * significant number is a country code immediately followed by the national digits; for each
487	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
488	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
489	     * left unchecked.
490	     *
491	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
492	     * @param rejectedValue             the raw telephone value, reported on rejection
493	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
494	     */
495	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
496	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
497	            String countryCode = rule.getKey();
498	            if (nationalSignificantNumber.startsWith(countryCode)) {
499	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
500	                if (nationalDigits != rule.getValue()) {
501	                    throw new InvalidTelephoneException(rejectedValue);
502	                }
503	                return;
504	            }
505	        }
506	    }
507	
508	    /**
509	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
510	     * value is treated as absent and returns {@code null}); when present the value must be a
511	     * syntactically valid address, and is stored and returned lower-cased.
512	     *
513	     * @param email the raw email value as submitted, may be {@code null}
514	     * @return the lower-cased email, or {@code null} when none was supplied
515	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
516	     */
517	    private String normalizeEmail(String email) {
518	        if (email == null || email.isBlank()) {
519	            return null;
520	        }
521	        String normalized = email.trim().toLowerCase();
522	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
523	            throw new InvalidEmailException(email);
524	        }
525	        return normalized;
526	    }
527	
528	    /**
529	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
530	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
531	     * key is the normalized telephone, email and householdId joined together, this one check
532	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
533	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
534	     * with different telephones have different keys and are both allowed.
535	     *
536	     * @param owner the owner being created, with its normalized telephone, email and householdId
537	     *              already applied
538	     * @throws DuplicateIdentityException if another owner already has the same identityKey
539	     */
540	    private void rejectDuplicateIdentity(Owner owner) {
541	        String identityKey = identityKey(owner);
542	        boolean inUse = this.clinicService.findAllOwners().stream()
543	            .map(this::identityKey)
544	            .anyMatch(identityKey::equals);
545	        if (inUse) {
546	            throw new DuplicateIdentityException(identityKey);
547	        }
548	    }
549	
550	    /**
551	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
552	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
553	     * duplicate decision is made by comparing whole identityKeys.
554	     *
555	     * @param owner the owner whose identityKey to derive
556	     * @return the derived identityKey
557	     */
558	    private String identityKey(Owner owner) {
559	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
560	        String email = owner.getEmail() == null ? "" : owner.getEmail();
561	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
562	        return telephone + "|" + email + "|" + householdId;
563	    }
564	
565	    /**
566	     * Applies the household rule to an owner being created. An owner belongs to the same household
567	     * as an existing owner when their lastName and address both match (compared case-insensitively
568	     * with runs of whitespace collapsed to a single space).
569	     *
570	     * <p>When no such existing owner exists there is nothing to do. Otherwise the new owner and
571	     * every existing owner in the household are assigned the same stable
572	     * {@link #householdId(String, String) householdId}. The household itself is no longer a
573	     * rejection: duplicate detection is now decided solely by the whole {@code identityKey}, of
574	     * which the householdId is one segment, so two members of the same household with different
575	     * telephones have different keys and are both allowed.
576	     *
577	     * @param owner the owner being created
578	     */
579	    private void applyHousehold(Owner owner) {
580	        String lastNameKey = toHouseholdKey(owner.getLastName());
581	        String addressKey = toHouseholdKey(owner.getAddress());
582	        List<Owner> household = this.clinicService.findAllOwners().stream()
583	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
584	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
585	            .toList();
586	        if (household.isEmpty()) {
587	            return;
588	        }
589	        String householdId = householdId(lastNameKey, addressKey);
590	        owner.setHouseholdId(householdId);
591	        for (Owner existing : household) {
592	            if (!householdId.equals(existing.getHouseholdId())) {
593	                existing.setHouseholdId(householdId);
594	                this.clinicService.saveOwner(existing);
595	            }
596	        }
597	    }
598	
599	    /**
600	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
601	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
602	     * lastName and address keys. Being a pure function of the household, every owner in it derives
603	     * the same value regardless of creation order.
604	     *
605	     * @param lastNameKey the normalized household lastName key
606	     * @param addressKey  the normalized household address key
607	     * @return the household identifier
608	     */
609	    private String householdId(String lastNameKey, String addressKey) {
610	        try {
611	            byte[] digest = MessageDigest.getInstance("SHA-256")
612	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
613	            StringBuilder hex = new StringBuilder(digest.length * 2);
614	            for (byte b : digest) {
615	                hex.append(String.format("%02x", b));
616	            }
617	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
618	        } catch (NoSuchAlgorithmException ex) {
619	            throw new IllegalStateException("SHA-256 not available", ex);
620	        }
621	    }
622	
623	    /**
624	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
625	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
626	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
627	     * string.
628	     */
629	    private String toHouseholdKey(String value) {
630	        if (value == null) {
631	            return "";
632	        }
633	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
634	    }
635	
636	    /**
637	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
638	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
639	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
640	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
641	     * value, or one that is blank once trimmed, normalizes to an empty string.
642	     *
643	     * @param address the raw address value as submitted, may be {@code null}
644	     * @return the normalized address, or an empty string when none was supplied
645	     */
646	    private String normalizeAddress(String address) {
647	        if (address == null) {
648	            return "";
649	        }
650	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
651	        if (collapsed.isEmpty()) {
652	            return "";
653	        }
654	        String[] tokens = collapsed.split(" ");
655	        StringBuilder normalized = new StringBuilder(collapsed.length());
656	        for (int i = 0; i < tokens.length; i++) {
657	            if (i > 0) {
658	                normalized.append(' ');
659	            }
660	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
661	        }
662	        return normalized.toString();
663	    }
664	
665	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
666	    @Override
667	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
668	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
669	        if (currentOwner == null) {
670	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
671	        }
672	        currentOwner.setAddress(ownerFieldsDto.getAddress());
673	        currentOwner.setCity(ownerFieldsDto.getCity());
674	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
675	        currentOwner.setLastName(ownerFieldsDto.getLastName());
676	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
677	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
678	        this.clinicService.saveOwner(currentOwner);
679	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
680	    }
681	
682	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
683	    @Transactional
684	    @Override
685	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
686	        Owner owner = this.clinicService.findOwnerById(ownerId);
687	        if (owner == null) {
688	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
689	        }
690	        this.clinicService.deleteOwner(owner);
691	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
692	    }
693	
694	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
695	    @Override
696	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
697	        Owner owner = this.clinicService.findOwnerById(ownerId);
698	        if (owner == null) {
699	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
700	        }
701	        HttpHeaders headers = new HttpHeaders();
702	        Pet pet = petMapper.toPet(petFieldsDto);
703	        owner.setId(ownerId);
704	        pet.setOwner(owner);
705	        pet.getType().setName(null);
706	        this.clinicService.savePet(pet);
707	        PetDto petDto = petMapper.toPetDto(pet);
708	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
709	            .buildAndExpand(pet.getId()).toUri());
710	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
711	    }
712	
713	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
714	    @Override
715	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
716	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
717	        if (currentOwner != null) {
718	            Pet currentPet = this.clinicService.findPetById(petId);
719	            if (currentPet != null) {
720	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
721	                currentPet.setName(petFieldsDto.getName());
722	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
723	                this.clinicService.savePet(currentPet);
724	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
725	            }
726	        }
727	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
728	    }
729	
730	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
731	    @Override
732	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
733	        HttpHeaders headers = new HttpHeaders();
734	        Visit visit = visitMapper.toVisit(visitFieldsDto);
735	        Pet pet = new Pet();
736	        pet.setId(petId);
737	        visit.setPet(pet);
738	        this.clinicService.saveVisit(visit);
739	        VisitDto visitDto = visitMapper.toVisitDto(visit);
740	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
741	            .buildAndExpand(visit.getId()).toUri());
742	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
743	    }
744	
745	
746	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
747	    @Override
748	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
749	        Owner owner = this.clinicService.findOwnerById(ownerId);
750	        if (owner != null) {
751	            Pet pet = owner.getPet(petId);
752	            if (pet != null) {
753	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
754	            }
755	        }
756	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
757	    }
758	}
